#include <bits/stdc++.h>
using namespace std;
using ll = long long;

int n;
vector<int> w;
vector<vector<int>> adj;
vector<int> down, up;
vector<ll> ans;

void dfsDown(int u, int p) {
    down[u] = w[u];
    for (int v : adj[u]) {
        if (v == p) continue;
        dfsDown(v, u);
        if (down[v] > down[u]) {
            down[u] = down[v];
        }
    }
}

void dfsUp(int u, int p) {
    ll total = up[u];
    int mx1 = -1, mx2 = -1;
    for (int v : adj[u]) {
        if (v == p) continue;
        total += down[v];
        if (down[v] > mx1) {
            mx2 = mx1;
            mx1 = down[v];
        } else if (down[v] > mx2) {
            mx2 = down[v];
        }
    }
    ans[u] = total;

    int use = max(up[u], w[u]);
    for (int v : adj[u]) {
        if (v == p) continue;
        int best = (down[v] == mx1) ? mx2 : mx1;
        up[v] = max(use, best);
        dfsUp(v, u);
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> n;
    w.resize(n);
    for (int i = 0; i < n; i++) {
        cin >> w[i];
    }
    adj.assign(n, {});
    for (int i = 0; i < n - 1; i++) {
        int u, v;
        cin >> u >> v;
        --u; --v;
        adj[u].push_back(v);
        adj[v].push_back(u);
    }

    down.assign(n, 0);
    up.assign(n, 0);
    ans.assign(n, 0);

    dfsDown(0, -1);
    dfsUp(0, -1);

    for (int i = 0; i < n; i++) {
        cout << ans[i] << (i + 1 < n ? ' ' : '\n');
    }
    return 0;
}
